from collections import deque
import json

def can_reach_boundary(grid, target_color):
    rows, cols = len(grid), len(grid[0])
    boundary_region = set()
    queue = deque()

    for r in range(rows):
        for c in range(cols):
            if grid[r][c] == target_color and (r == 0 or r == rows-1 or c == 0 or c == cols-1):
                boundary_region.add((r, c))
                queue.append((r, c))

    while queue:
        r, c = queue.popleft()
        for dr, dc in [(-1, 0), (1, 0), (0, -1), (0, 1)]:
            nr, nc = r + dr, c + dc
            if 0 <= nr < rows and 0 <= nc < cols:
                if grid[nr][nc] == target_color and (nr, nc) not in boundary_region:
                    boundary_region.add((nr, nc))
                    queue.append((nr, nc))
    return boundary_region

def apply_fill(grid, target_color=9):
    result = [row[:] for row in grid]
    boundary = can_reach_boundary(result, target_color)
    for r in range(len(result)):
        for c in range(len(result[0])):
            if result[r][c] == target_color and (r, c) not in boundary:
                result[r][c] = 4
    return result

